import{_ as r,o as a,c as l,a2 as e}from"./chunks/framework.BXzK3EA4.js";const S=JSON.parse('{"title":"Darkest Dungeon (2016) — 게임 로직 백과사전","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-Darkest-Dungeon.md","filePath":"rules/Ref-Darkest-Dungeon.md"}'),o={name:"rules/Ref-Darkest-Dungeon.md"};function i(d,t,s,n,h,u){return a(),l("div",null,[...t[0]||(t[0]=[e('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>출처 인계: <a href="https://github.com/islee23520/seoul-kenshi/blob/docs/reference-context-sync-st_01a079f1/.omo/research/README.md" target="_blank" rel="noreferrer">공유 조사 색인</a>. 로컬 sources.json·원문 패킷 언급은 조사 당시 기록이며 이 전달에 원시 자료가 포함된다는 뜻이 아니다. 누락된 ID는 미확인으로 남긴다. 자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(<code>darkest-dungeon.md</code>)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다.</p></blockquote><h1 id="darkest-dungeon-2016-—-게임-로직-백과사전" tabindex="-1">Darkest Dungeon (2016) — 게임 로직 백과사전 <a class="header-anchor" href="#darkest-dungeon-2016-—-게임-로직-백과사전" aria-label="Permalink to &quot;Darkest Dungeon (2016) — 게임 로직 백과사전&quot;">​</a></h1><blockquote><p>Red Hook Studios, 2016. 1월 (DLC: The Crimson Court / The Shieldbreaker / The Color of Madness / Butcher&#39;s Circus). 고딕 호러 로그라이트 턴제 RPG. 모든 수치는 Radiant/Darkest 난이도 기준.</p><p><strong>출처 표기</strong>: [S-01]~[S-09]는 문서 말미 출처 목록 참조. [문서]/[추론]/[미확인]으로 신뢰도 표기.</p></blockquote><h2 id="_1-개요" tabindex="-1">1. 개요 <a class="header-anchor" href="#_1-개요" aria-label="Permalink to &quot;1. 개요&quot;">​</a></h2><ul><li><strong>장르</strong>: 사이드뷰 턴제 전투 + 던전 탐사 로그라이트 + 영지(햄릿) 경영. 조상(Ancestor)이 불러온 재앙을 청소하는 것이 전체 전제 [S-09][문서].</li><li><strong>핵심 특징(설계 철학)</strong>: <ol><li><strong>소모품 같은 영웅</strong>: 영웅은 영구사망하며, 로스터는 Stage Coach에서 무료로 계속 보충. 핵심 난이도는 적의 강함이 아니라 <strong>스트레스·부상·소모의 누적(Attrition)</strong> [S-01][문서].</li><li><strong>스트레스가 체력보다 중요한 2중 HP</strong>: HP는 퀘스트 끝나면 회복되지만 스트레스는 마을에서 금화를 써야 치료 [S-02][문서].</li><li><strong>빛·어둠 리스크-리워드</strong>: 횃불 게이지는 안전과 이익 사이의 슬라이더 [S-04][문서].</li><li><strong>불완전한 제어</strong>: 영웅은 괴벽(Quirk)·질병·공포(Affliction)으로 플레이어 명령을 거부할 수 있다 [S-01][S-07][문서].</li></ol></li></ul><h2 id="_2-코어-루프" tabindex="-1">2. 코어 루프 <a class="header-anchor" href="#_2-코어-루프" aria-label="Permalink to &quot;2. 코어 루프&quot;">​</a></h2><p>주 단위(1 week = 1 던전 원정) [S-03][S-05][추론]:</p><ol><li><strong>햄릿</strong>: 로스터 점검 → 스트레스 치료, 괴벽 치료, 업그레이드, 모집</li><li><strong>원정 선택</strong>: 지역 4곡 + 최종 던전. 난이도(견습/숙련/챔피언) × 길이(짧음/중간/긺)</li><li><strong>보급(Provisioning)</strong>: 횃불·식량·삽·해독제 등 금화로 구입 [S-06][문서]</li><li><strong>탐사·전투</strong>: 방-복도 그리드 이동, 전투, 큐리오 상호작용, 야영</li><li><strong>귀환·정산</strong>: 보상 + 무작위 괴벽/질병 획득</li><li>보스 잠금 해제 진척도 → 보스 원정 → 지역 레벨업 → 반복</li></ol><h2 id="_3-진행-구조" tabindex="-1">3. 진행 구조 <a class="header-anchor" href="#_3-진행-구조" aria-label="Permalink to &quot;3. 진행 구조&quot;">​</a></h2><h3 id="_3-1-원정-길이-s-03-문서" tabindex="-1">3.1 원정 길이 [S-03][문서] <a class="header-anchor" href="#_3-1-원정-길이-s-03-문서" aria-label="Permalink to &quot;3.1 원정 길이 [S-03][문서]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>길이</th><th>구성</th><th>야영</th><th>특징</th></tr></thead><tbody><tr><td>짧음</td><td>소수의 방</td><td>0</td><td>위험·보상 최소. 야영 불가</td></tr><tr><td>중간</td><td>분기 던전</td><td>1</td><td>보스 퀘스트는 항상 중간</td></tr><tr><td>긺</td><td>극단적 분기</td><td>2</td><td>식량·횃불 대량, 스트레스 관리 필수</td></tr></tbody></table><h3 id="_3-2-난이도-3단계-s-03-문서" tabindex="-1">3.2 난이도 3단계 [S-03][문서] <a class="header-anchor" href="#_3-2-난이도-3단계-s-03-문서" aria-label="Permalink to &quot;3.2 난이도 3단계 [S-03][문서]&quot;">​</a></h3><ul><li>견습 = 결의 레벨 1 / 숙련 = 3 / 챔피언 = 5</li><li>영웅이 퀘스트보다 <strong>2레벨 이상 높으면 참가 거부</strong>. 낮으면 입장 시 레벨당 스트레스 +20</li></ul><h3 id="_3-3-퀘스트-목표-s-03-문서" tabindex="-1">3.3 퀘스트 목표 [S-03][문서] <a class="header-anchor" href="#_3-3-퀘스트-목표-s-03-문서" aria-label="Permalink to &quot;3.3 퀘스트 목표 [S-03][문서]&quot;">​</a></h3><p>청소 / 탐색 / 수집 / 활성화 / 보스 / 최종 던전(<strong>중도 퇴각 시 영웅 1명 사망</strong>)</p><h3 id="_3-4-결의-경험치-s-03-문서" tabindex="-1">3.4 결의 경험치 [S-03][문서] <a class="header-anchor" href="#_3-4-결의-경험치-s-03-문서" aria-label="Permalink to &quot;3.4 결의 경험치 [S-03][문서]&quot;">​</a></h3><p>견습 2/3/4, 숙련 4/6/8, 챔피언 8/12/16. 결의 레벨 0~6.</p><h2 id="_4-경제-시스템" tabindex="-1">4. 경제 시스템 <a class="header-anchor" href="#_4-경제-시스템" aria-label="Permalink to &quot;4. 경제 시스템&quot;">​</a></h2><h3 id="_4-1-자원-s-03-s-05-s-06-문서" tabindex="-1">4.1 자원 [S-03][S-05][S-06][문서] <a class="header-anchor" href="#_4-1-자원-s-03-s-05-s-06-문서" aria-label="Permalink to &quot;4.1 자원 [S-03][S-05][S-06][문서]&quot;">​</a></h3><ul><li><strong>금화</strong>: 보급·치료·업그레이드. 항상 부족한 흐름 자원</li><li><strong>유물 4종</strong> — 건물 업그레이드 전용: Bust(Abbey/Sanitarium), Deed(Blacksmith/StageCoach), Portrait(Guild/Tavern), Crest(만능 하위)</li><li><strong>장신구</strong>: 매각 750~7500(조상급) [S-08][문서]</li><li><strong>보급품</strong>: 원정 시작 시만 구입, 귀환 시 극히 일부만 환급 → 과다 구입은 순수 손해 [S-06][문서]</li></ul><h3 id="_4-2-보급-목록-s-06-문서" tabindex="-1">4.2 보급 목록 [S-06][문서] <a class="header-anchor" href="#_4-2-보급-목록-s-06-문서" aria-label="Permalink to &quot;4.2 보급 목록 [S-06][문서]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>품목</th><th>가격</th><th>효과</th></tr></thead><tbody><tr><td>식량</td><td>75</td><td>소회복+기아 방지</td></tr><tr><td>횃불</td><td>75</td><td>광원 +25</td></tr><tr><td>삽</td><td>250</td><td>장애물 제거</td></tr><tr><td>해독제</td><td>150</td><td>Blight 치료</td></tr><tr><td>붕대</td><td>150</td><td>Bleed 치료</td></tr><tr><td>약초</td><td>200</td><td>디버프/질병 치료</td></tr><tr><td>해골열쇠</td><td>200</td><td>상자/문</td></tr><tr><td>성수</td><td>150</td><td>저항 버프</td></tr></tbody></table><p>클래스별 무료 보급: 성기사=성수, 역병의사=해독제, 도굴꾼=삽, 석궁병=붕대, 골동품상=해골열쇠 [S-06][문서]</p><h2 id="_5-캐릭터-파티-시스템" tabindex="-1">5. 캐릭터/파티 시스템 <a class="header-anchor" href="#_5-캐릭터-파티-시스템" aria-label="Permalink to &quot;5. 캐릭터/파티 시스템&quot;">​</a></h2><h3 id="_5-1-기본-구조-s-01-문서" tabindex="-1">5.1 기본 구조 [S-01][문서] <a class="header-anchor" href="#_5-1-기본-구조-s-01-문서" aria-label="Permalink to &quot;5.1 기본 구조 [S-01][문서]&quot;">​</a></h3><ul><li><strong>파티 = 4명</strong>, 위치 1~4번. 많은 스킬이 위치 조건부</li><li><strong>클래스 15+2종</strong>: 성기사, 도적, 광대, 역병의사, 성녀, 점성술사, 나병환자, 여전사, 사냥꾼, 현상금사냥꾼, 그레이브로버, 아버미네이션, 골동품상, 석궁병 + DLC: 채찍질자, 실드브레이커</li><li>전투 스킬 7개 중 4개 활성(전투 중 교체 불가), 야영 스킬 7개 중 4개 [S-01][문서]</li><li>주요 6스탯: ACC, CRIT, DMG, DODGE, PROT(상한 80%), SPD. 명중 = 스킬 기본명중 + ACC + 숨은 +5 − 대상 DODGE [S-01][문서]</li></ul><h3 id="_5-2-로스터-관리" tabindex="-1">5.2 로스터 관리 <a class="header-anchor" href="#_5-2-로스터-관리" aria-label="Permalink to &quot;5.2 로스터 관리&quot;">​</a></h3><ul><li>Stage Coach <strong>매주 무료 모집</strong>, 업그레이드로 로스터 상한·모집 레벨 확대 [S-05][문서]</li><li>스트레스 회복 시설은 <strong>1주일 점유</strong> → 넓은 로스터가 필수 [S-02][S-05][추론]</li><li>로스터 방치 시 주당 스트레스 5 회복 [S-02][문서]</li></ul><h3 id="_5-3-스트레스-시스템-핵심-s-02-문서" tabindex="-1">5.3 스트레스 시스템 (핵심) [S-02][문서] <a class="header-anchor" href="#_5-3-스트레스-시스템-핵심-s-02-문서" aria-label="Permalink to &quot;5.3 스트레스 시스템 (핵심) [S-02][문서]&quot;">​</a></h3><ul><li>게이지 0~200. 획득원: 적 스트레스 공격·치명타(10+동료 5), 던전 입장, 함정, 기아, 동료 사망 목격</li><li><strong>100 도달 시 결의 시험</strong>: 소확률 <strong>미덕(Virtue)</strong> — 스트레스 45 리셋+버프. 그 외 <strong>공포(Affliction)</strong> — 명령 불복종 [S-02][문서]</li><li><strong>200 도달 시 심장마비</strong>: 즉시 사경 진입, 사경 상태였다면 즉사 [S-02][문서]</li><li>회복: 마을 시설(금화, 1주), 캠핑, 전투 스킬, 치명타 성공 시 3, 적 처치 50%로 3 [S-02][문서]</li><li>퀘스트 완료로 HP는 회복되지만 <strong>스트레스는 100에서 캡</strong> [S-02][문서]</li></ul><h3 id="_5-4-괴벽-quirk-시스템-s-07-문서" tabindex="-1">5.4 괴벽(Quirk) 시스템 [S-07][문서] <a class="header-anchor" href="#_5-4-괴벽-quirk-시스템-s-07-문서" aria-label="Permalink to &quot;5.4 괴벽(Quirk) 시스템 [S-07][문서]&quot;">​</a></h3><ul><li>영웅당 긍정 최대 5 + 부정 최대 5</li><li>획득: 모집 시(긍정1+부정1 보장), 원정 후(성공 시 긍정 50−0.1×스트레스/부정 30+0.2×스트레스)</li><li>부정 괴벽은 <strong>미션마다 25% 확률로 자가 고착</strong> [S-07][문서]</li><li>요양원: 금화로 부정 제거·긍정 고착 [S-07][문서]</li></ul><h3 id="_5-5-질병과-죽음-s-01-문서" tabindex="-1">5.5 질병과 죽음 [S-01][문서] <a class="header-anchor" href="#_5-5-질병과-죽음-s-01-문서" aria-label="Permalink to &quot;5.5 질병과 죽음 [S-01][문서]&quot;">​</a></h3><ul><li><strong>사망은 영구</strong>. 투자 전부 소실. 사망 원인: 직접 피해, 사경 추가 피해(Deathblow), 심장마비, 출혈/독, 최종 던전 퇴각</li><li>유일한 부활: 마을 이벤트 &quot;From Beyond&quot;(희귀) [S-01][문서]</li></ul><h2 id="_6-전투-시스템" tabindex="-1">6. 전투 시스템 <a class="header-anchor" href="#_6-전투-시스템" aria-label="Permalink to &quot;6. 전투 시스템&quot;">​</a></h2><ul><li>턴제, 유닛당 1행동. 순서 = SPD + 무작위 1~8 [S-01][S-03][문서]</li><li>포메이션: 아군 1~4 ↔ 적 1~4(Large는 2칸). 이동(Move) 기술로 위치 재편이 핵심</li><li><strong>치명타</strong>: 1.5배 + DoT 2턴 연장. 영웅 치명타 = 스트레스 −3, 적 치명타 = 스트레스 +10 [S-01][문서]</li><li><strong>치명적 치유</strong>: 12% 확률, 회복량 2배 [S-01][문서]</li><li><strong>시체(Corpse)</strong>: 죽은 적이 자리 유지 → 위치 전략에 영향 [S-01][추론]</li><li><strong>스톨링 규칙</strong>: 회복/버프 2회 이상 + 잔여 적 2 이하면 증원군 소환 [S-01][문서]</li><li><strong>표식(Mark) 시너지</strong>: 표적+표식 소비 딜러 조합이 대표 빌드 [S-01][문서]</li></ul><h2 id="_7-지도-세계-구조" tabindex="-1">7. 지도/세계 구조 <a class="header-anchor" href="#_7-지도-세계-구조" aria-label="Permalink to &quot;7. 지도/세계 구조&quot;">​</a></h2><ul><li><strong>세계 = 부동산(Estate)</strong>: 햄릿 + 4개 지역 던전 + 최종 던전 [S-05][문서] <ul><li>폐허(언데드) / 우리(인간·야수) / 숲(야생) / 만(엘드리치, PROT 높음)</li></ul></li><li><strong>던전 = 방+복도 그리드</strong>. 이동 시 광원 소모(신규 6/재방문 1) [S-03][S-04][문서]</li><li><strong>정찰</strong>: 방 입장 시 확률 발동 — 함정/전투/보물 사전 표시 [S-03][문서]</li></ul><h3 id="광원-light-meter-s-04-문서" tabindex="-1">광원(Light Meter) [S-04][문서] <a class="header-anchor" href="#광원-light-meter-s-04-문서" aria-label="Permalink to &quot;광원(Light Meter) [S-04][문서]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>구간</th><th>스트레스</th><th>적 버프</th><th>전리품</th><th>아군 CRIT</th></tr></thead><tbody><tr><td>밝음(76+)</td><td>—</td><td>—</td><td>0%</td><td>—</td></tr><tr><td>흐림(51-75)</td><td>+10%</td><td>—</td><td>25%×1</td><td>—</td></tr><tr><td>어스름(26-50)</td><td>+20%</td><td>+5/+10%</td><td>50%×1</td><td>+1</td></tr><tr><td>어둠(1-25)</td><td>+30%</td><td>+10/+15%</td><td>75%×1</td><td>+2</td></tr><tr><td>칠흑(0)</td><td>+40%</td><td>+12.5/+25%</td><td>75%×2</td><td>+3</td></tr></tbody></table><ul><li>칠흑 복도 전투 시 Shambler 기습 확률(견습 1%/숙련 8%/챔피언 12%) [S-04][문서]</li></ul><h2 id="_8-외교-세력" tabindex="-1">8. 외교/세력 <a class="header-anchor" href="#_8-외교-세력" aria-label="Permalink to &quot;8. 외교/세력&quot;">​</a></h2><p>전통적 외교 없음. 대응 개념 [S-07][추론]:</p><ul><li><strong>적 유형 대응</strong>: Unholy/Beast/Human/Eldritch에 따라 괴벽·장신구 효율 갈림</li><li><strong>마을 이벤트</strong>: 원정 성공 유형에 따라 호재/악재 [S-03][문서]</li><li><strong>지구(Districts, CC DLC)</strong>: 청사진+유물로 건설하는 패시브 시설 [S-05][문서]</li><li><strong>조상 스토리</strong>: 4개 지역 보스 각각의 기원이 조상의 죄 [S-09][문서]</li></ul><h2 id="_9-이벤트-내러티브" tabindex="-1">9. 이벤트/내러티브 <a class="header-anchor" href="#_9-이벤트-내러티브" aria-label="Permalink to &quot;9. 이벤트/내러티브&quot;">​</a></h2><ul><li><strong>서술자 = 조상</strong>: 회고 형식. 지역 보스 처치로 회고록 해금 [S-05][S-09][문서]</li><li>곡선: 쾌락에 물든 귀족 → 금지된 지식 → 굴착이 열어버린 심연 → 후손에게 유산과 청소 의무</li><li><strong>최종 보스 2단계</strong>: 조상(무적, 반영체 소환) → 어둠의 심장 — 세계 자체가 악이었음이 드러나는 결말 [S-09][문서]</li><li>던전 이벤트: 함정, 기아 체크, 밤 습격, 큐리오 상호작용 [S-03][문서]</li><li>&quot;계속 탐사할 것인가 vs 지금 떠날 것인가&quot; — 매 원정의 이탈 판단이 핵심 선택 [추론]</li></ul><h2 id="_10-난이도-압박" tabindex="-1">10. 난이도/압박 <a class="header-anchor" href="#_10-난이도-압박" aria-label="Permalink to &quot;10. 난이도/압박&quot;">​</a></h2><p><strong>설계 원칙: 원시적 강함이 아니라 마모로 죽인다(Attrition over raw power)</strong> [추론]</p><p>압박원:</p><ol><li><strong>스트레스 잔존</strong>: HP는 공짜 회복, 스트레스는 금화·시간 요구 [S-02][문서]</li><li><strong>영구사망+투자 손실</strong>: 죽으면 박은 금화·유물 전부 소실 [S-01][문서]</li><li><strong>괴벽 자동 악화</strong>: 원정마다 부정 괴벽 확률+25% 자가 고착 [S-07][문서]</li><li><strong>광원 경제</strong>: 안전(횃불=금화) vs 이익(어둠=스트레스·Shambler) [S-04][문서]</li><li><strong>퇴각 비용</strong>: 스트레스+부정 괴벽; 최종 던전 퇴각=영웅 1명 처형 [S-03][문서]</li><li><strong>확률의 층위</strong>: 95% 표시도 연속 미스 가능(연속 미스 +4 ACC 보정 존재) [S-01][문서]</li><li><strong>경제 유출</strong>: 성공해도 치료·보급이 수입 잠식 [추론]</li></ol><h2 id="부록-햄릿-건물-s-05-문서" tabindex="-1">부록: 햄릿 건물 [S-05][문서] <a class="header-anchor" href="#부록-햄릿-건물-s-05-문서" aria-label="Permalink to &quot;부록: 햄릿 건물 [S-05][문서]&quot;">​</a></h2><table tabindex="0"><thead><tr><th>건물</th><th>기능</th><th>유물</th></tr></thead><tbody><tr><td>Stage Coach</td><td>영웅 무료 모집</td><td>Deed/Crest</td></tr><tr><td>Blacksmith</td><td>무기·방어구 강화</td><td>Deed/Crest</td></tr><tr><td>Guild</td><td>전투 스킬 강화</td><td>Portrait/Crest</td></tr><tr><td>Sanitarium</td><td>괴벽 제거·질병 치료</td><td>Bust/Crest</td></tr><tr><td>Tavern</td><td>스트레스 치료(부작용 높음)</td><td>Portrait/Crest</td></tr><tr><td>Abbey</td><td>스트레스 치료(부작용 낮음)</td><td>Bust/Crest</td></tr><tr><td>Nomad Wagon</td><td>장신구 판매</td><td>Crest</td></tr></tbody></table><h2 id="부록-장신구-s-08-문서" tabindex="-1">부록: 장신구 [S-08][문서] <a class="header-anchor" href="#부록-장신구-s-08-문서" aria-label="Permalink to &quot;부록: 장신구 [S-08][문서]&quot;">​</a></h2><ul><li>영웅당 2개. 희귀도: 매우흔함→조상급(유니크)</li><li>보스 원정은 항상 매우희귀. 거의 모든 장신구에 트레이드오프 페널티 — &quot;완벽한 장비&quot; 없음</li></ul><h2 id="출처" tabindex="-1">출처 <a class="header-anchor" href="#출처" aria-label="Permalink to &quot;출처&quot;">​</a></h2><ul><li>[S-01]~[S-09] Darkest Dungeon Wiki api.php (2026-09-06): Heroes, Stress, Expedition, Light Meter, Hamlet, Provisions, Quirks, Trinkets, Ancestor</li></ul>',57)])])}const c=r(o,[["render",i]]);export{S as __pageData,c as default};
